import re
from ..section_generic import TextBasedSectionGeneric
from ..utils.logger import logger


class SectionEnb(TextBasedSectionGeneric):
    """
    Section "enb" is a part of cus.ini config file.
    Generated content base on enb.yaml.
    Example generated for CLOUD_R4A_CUS:

    [enb_1]
    enb_type = FLEXI
    """

    def __init__(self, subsection_separator='\n'):
        super().__init__(subsection_separator)
        self._section_header = '[enb_{}]'

    def _prepare_section_content(self, ue_config, enb_config, *args, **kwargs):
        for key in self._get_enbs_keys(enb_config, ue_config):
            enb_num = re.search(r'\d+', key).group(0)
            logger.debug("Generating ENB section id {}".format(enb_num))
            subsection_content = [
                self._section_header.format(enb_num),
                'enb_type = FLEXI'
            ]
            self._section_content.append(subsection_content)

    @staticmethod
    def _get_enbs_keys(enb_config, ue_config):
        real_enbs = list(enb_config.keys())
        fake_enbs = []
        for key in filter(lambda x: re.match(r'fake', x), ue_config.keys()):
            fake_enbs.extend([re.search(r'enb_\d+', key).group()])
        return sorted(set(real_enbs + fake_enbs))
